CREATE OR REPLACE PROCEDURE sp(
  para_Start_year integer,
  para_Club_name text,
  para_Club_ID integer,
  para_Player_ID integer,
  para_Occupation text,
  para_Votes integer
)
LANGUAGE plpgsql
AS $$
DECLARE
  spar_trace integer := para_Start_year;
  ref_player_id integer := COALESCE(para_Player_ID, 0);
  phase integer;
BEGIN
  FOR phase IN 1..9 LOOP
    UPDATE club SET "Club_name" = 'phase_' || phase
    WHERE "Start_year" >= spar_trace;

    DELETE FROM club
    WHERE "Club_ID" < para_Club_ID + phase - 1;

    UPDATE player SET "Occupation" = 'log_phase_' || phase
    WHERE "Player_ID" >= ref_player_id;

    DELETE FROM player
    WHERE "Votes" < para_Votes + phase - 1;
  END LOOP;
END;
$$;

